"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["84264"],{96516(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.pagina_codigo_duplicado","status":422,"titulo":"O c\xf3digo de p\xe1gina se repete no formul\xe1rio"},"descricao":{"codigo":"uniplus.estrutura_formulario.pagina_codigo_duplicado","requisitos":[],"oQueAconteceu":["Duas p\xe1ginas do formul\xe1rio t\xeam o mesmo `codigo`. O c\xf3digo \xe9 o que os itens e os grupos usam em `paginaCodigo` para dizer em que se\xe7\xe3o est\xe3o, e por isso \xe9 \xfanico no formul\xe1rio. A compara\xe7\xe3o \xe9 exata e diferencia mai\xfasculas de min\xfasculas. A mensagem \xe9 \\"Existe outra p\xe1gina com o mesmo c\xf3digo no formul\xe1rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `paginas[i].codigo`; nos modelos de formul\xe1rio o caminho come\xe7a por `conteudo.paginas`. Nada \xe9 gravado. A entrada aponta a segunda ocorr\xeancia e as seguintes; a primeira fica de fora da recusa.","A estrutura das p\xe1ginas s\xf3 \xe9 conferida quando todas as p\xe1ginas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada p\xe1gina \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as p\xe1ginas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as p\xe1ginas s\xf3 depois que a estrutura das p\xe1ginas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["D\xea a cada p\xe1gina um `codigo` distinto e, se h\xe1 itens ou grupos que apontavam para a p\xe1gina repetida, confira o `paginaCodigo` deles. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);